def verify():
    assert abs(10 + 10 * math.log10(2) - 13.01) < 0.01 and abs(10 ** 0.96 - 9.12) < 0.01
    assert abs(1e6 * 1.25 / 2 - 625e3) < 1e-6 and abs(2e9 * 1e-6 - 2000) < 1e-9
    assert abs(1 / 15000 * 1e6 - 66.67) < 0.01 and abs(4.7 / (66.7 + 4.7) * 100 - 6.58) < 0.01 and 4 * math.log2(16) == 16


if __name__ == "__main__":
    verify()
    write_subject(SUBJECT, U)
